const CAUSA_TURNSTILE_SITE_KEY='0x4AAAAAAFpOoLtbZ84hNrxj';
function CausaCaptcha({onToken}){
 const ref=React.useRef(null);
 React.useEffect(()=>{
  let alive=true,widgetId=null;
  function render(){
   if(!alive||!ref.current||!window.turnstile)return;
   if(widgetId!==null)return;
   widgetId=window.turnstile.render(ref.current,{sitekey:CAUSA_TURNSTILE_SITE_KEY,
    callback:token=>onToken(token),
    'expired-callback':()=>onToken(''),
    'error-callback':()=>onToken('')});
  }
  if(window.turnstile)render();
  else{
   let script=document.querySelector('script[data-causa-turnstile]');
   if(!script){script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.defer=true;script.dataset.causaTurnstile='1';document.head.appendChild(script)}
   script.addEventListener('load',render);
  }
  return()=>{alive=false;const script=document.querySelector('script[data-causa-turnstile]');script?.removeEventListener('load',render);if(widgetId!==null&&window.turnstile){try{window.turnstile.remove(widgetId)}catch{}}onToken('')};
 },[]);
 return <div ref={ref} aria-label="Verifikasi keamanan CAPTCHA"/>;
}

const navs=[['dashboard','Ringkasan',LayoutDashboard],['pos','Kasir / POS',ShoppingBag],['barista','Dapur & Barista',Coffee],['history','Riwayat Transaksi',Receipt],['products','Manajemen Menu',UtensilsCrossed],['stock','Stok Bahan',Package],['finance','Keuangan',Wallet],['staff','Karyawan & Absensi',Users],['qr','Menu Digital & QR',QrCode]];
